-- PostgreSQL. For MySQL replace "GENERATED BY DEFAULT AS IDENTITY" with AUTO_INCREMENT
-- and "TIMESTAMP WITH TIME ZONE" with DATETIME(6). Rename the version to fit your Flyway sequence.

CREATE TABLE holidays (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date_ad     DATE         NOT NULL,
    date_bs     VARCHAR(16)  NOT NULL,
    name        VARCHAR(255) NOT NULL,
    type        VARCHAR(32)  NOT NULL,
    fetched_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uq_holidays_date_name UNIQUE (date_ad, name)
);
CREATE INDEX idx_holidays_date_ad ON holidays (date_ad);
CREATE INDEX idx_holidays_date_bs ON holidays (date_bs);

CREATE TABLE holiday_msg (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    holiday_id  BIGINT        NOT NULL REFERENCES holidays (id) ON DELETE CASCADE,
    variant     VARCHAR(16)   NOT NULL,
    ai_title    VARCHAR(255)  NOT NULL,
    ai_body     VARCHAR(2000) NOT NULL,
    title       VARCHAR(255)  NOT NULL,
    body        VARCHAR(2000) NOT NULL,
    source      VARCHAR(16)   NOT NULL,
    model       VARCHAR(64),
    edited_by   BIGINT,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uq_holiday_msg_variant UNIQUE (holiday_id, variant)
);

CREATE TABLE holiday_decision (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    holiday_id      BIGINT      NOT NULL UNIQUE REFERENCES holidays (id),
    status          VARCHAR(16) NOT NULL,
    selected_msg_id BIGINT REFERENCES holiday_msg (id),
    selected_by     BIGINT,
    auto_selected   BOOLEAN     NOT NULL DEFAULT FALSE,
    selected_at     TIMESTAMP WITH TIME ZONE,
    sent_at         TIMESTAMP WITH TIME ZONE,
    send_attempts   INT         NOT NULL DEFAULT 0,
    last_error      VARCHAR(500),
    created_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at      TIMESTAMP WITH TIME ZONE NOT NULL
);
CREATE INDEX idx_holiday_decision_status ON holiday_decision (status);

CREATE TABLE holiday_admin_status (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    holiday_id     BIGINT      NOT NULL REFERENCES holidays (id),
    holiday_msg_id BIGINT REFERENCES holiday_msg (id),
    admin_id       BIGINT      NOT NULL,
    action         VARCHAR(16) NOT NULL,
    acted_at       TIMESTAMP WITH TIME ZONE NOT NULL
);
CREATE INDEX idx_holiday_admin_status_holiday ON holiday_admin_status (holiday_id);
